async function route() {
  closeOverlay();
  closeSmallBox();
  const h = location.hash || '#/login';
  for (const r of routes) {
    const m = h.match(r.re);
    if (m) {
      try { await r.fn(...m.slice(1)); } catch (e) {
        showBanner(e.message || 'Request failed');
        if (e.status === 401) { ME = null; location.hash = '#/login'; }
      }
      return;
    }
  }
  location.hash = '#/login';
}

